"""The command database: menus, commands and parameters of RouterOS, generated by ``tools/gen_schema.py``.

The file is a tree of plain dictionaries. Short keys keep it small:

======  ==============================================================================================
``c``   children of a menu: name to node
``k``   1 for a command, absent for a menu
``a``   arguments of a command: name to argument
``r``   arguments the command cannot be compiled without
``u``   how many unnamed arguments the command takes (99 means more than three)
``d``   description
======  ==============================================================================================

An argument has ``d`` (description), ``t`` (type text), ``e`` (known values), ``x`` (1 when ``e`` is the complete list) and ``f``
(1 for a flag, which can be written without a value, like detail or count-only).
"""

from __future__ import annotations

import gzip
import json
import re
from collections.abc import Iterable, Mapping
from importlib import resources
from pathlib import Path
from typing import Any

NodeInfo = dict[str, Any]
ArgInfo = dict[str, Any]


class Match:
    """The result of looking a name up. ``kind`` is ``found``, ``ambiguous`` or ``none``."""

    __slots__ = ("candidates", "kind", "name", "value")

    def __init__(self, kind: str, name: str = "", value: Any = None, candidates: tuple[str, ...] = ()) -> None:
        self.kind = kind
        self.name = name
        self.value = value
        self.candidates = candidates


_NONE = Match("none")


def match_name(table: Mapping[str, Any] | None, word: str) -> Match:
    """RouterOS accepts any unambiguous prefix of a menu, command or argument name (docs/ambiguities.md C-10).

    An exact match wins even when it is also the prefix of a longer name.
    """
    if not table or word == "":
        return _NONE
    if word in table:
        return Match("found", word, table[word])
    candidates = [name for name in table if name.startswith(word)]
    if len(candidates) == 1:
        return Match("found", candidates[0], table[candidates[0]])
    if len(candidates) > 1:
        return Match("ambiguous", candidates=tuple(sorted(candidates)))
    return _NONE


def suggest(names: Iterable[str], word: str, limit: int = 3) -> list[str]:
    """Names close to ``word``, for "did you mean"."""
    scored: list[tuple[int, str]] = []
    for name in names:
        distance = _edit_distance(name, word)
        prefixy = name.startswith(word) or word.startswith(name)
        budget = max(1, max(len(name), len(word)) // 4)
        if distance <= budget or prefixy:
            scored.append((distance - 1 if prefixy else distance, name))
    scored.sort()
    return [name for _, name in scored[:limit]]


def _edit_distance(a: str, b: str) -> int:
    if abs(len(a) - len(b)) > 4:
        return 99
    previous = list(range(len(b) + 1))
    for i in range(1, len(a) + 1):
        row = [i]
        for j in range(1, len(b) + 1):
            row.append(min(previous[j] + 1, row[j - 1] + 1, previous[j - 1] + (0 if a[i - 1] == b[j - 1] else 1)))
        previous = row
    return previous[len(b)]


class Schema:
    def __init__(self, data: dict[str, Any]) -> None:
        self.data = data

    @property
    def root(self) -> NodeInfo:
        root: NodeInfo = self.data["root"]
        return root

    @property
    def version(self) -> str:
        return str(self.data["version"])

    @classmethod
    def from_json(cls, text: str) -> Schema:
        data = json.loads(text)
        if not isinstance(data, dict) or data.get("format") != 1 or "root" not in data:
            raise ValueError("not a routeros-lsp command database")
        return cls(data)

    @classmethod
    def from_file(cls, path: str | Path) -> Schema:
        raw = Path(path).read_bytes()
        if str(path).endswith(".gz"):
            raw = gzip.decompress(raw)
        return cls.from_json(raw.decode("utf-8"))

    @classmethod
    def bundled(cls) -> Schema | None:
        """The command database that ships with the package: the newest file in ``routeros_lsp/data``."""
        directory = resources.files("routeros_lsp").joinpath("data")
        if not directory.is_dir():
            return None
        names = [entry.name for entry in directory.iterdir() if re.fullmatch(r"routeros-.*\.json(\.gz)?", entry.name)]
        if not names:
            return None
        newest = max(names, key=_version_key)
        raw = directory.joinpath(newest).read_bytes()
        if newest.endswith(".gz"):
            raw = gzip.decompress(raw)
        return cls.from_json(raw.decode("utf-8"))


def _version_key(name: str) -> tuple[int, ...]:
    found = re.search(r"routeros-([\d.]+)", name)
    return tuple(int(part) for part in (found.group(1) if found else "0").split(".") if part.isdigit())
